use vstd::prelude::*;

// Helper functions to check case and convert characters,
// modeled via ASCII codes given Rust char values.

fn is_lowercase_alpha(c: char) -> bool {
    'a' <= c && c <= 'z'
}

fn is_uppercase_alpha(c: char) -> bool {
    'A' <= c && c <= 'Z'
}

fn to_uppercase(c: char) -> char {
    // Precondition: c is lowercase English letter
    requires(is_lowercase_alpha(c));
    guarantees(is_uppercase_alpha(result));
    // Convert via ASCII arithmetic: 'a' (0x61) to 'A' (0x41) difference is 32 decimal
    char::from_u32(c as u32 - 32).unwrap()
}

fn to_lowercase(c: char) -> char {
    // Precondition: c is uppercase English letter
    requires(is_uppercase_alpha(c));
    guarantees(is_lowercase_alpha(result));
    // Convert via ASCII arithmetic: 'A' (0x41) to 'a' (0x61) difference is 32 decimal
    char::from_u32(c as u32 + 32).unwrap()
}

fn toggle_case_char(c: char) -> char {
    if is_lowercase_alpha(c) {
        to_uppercase(c)
    } else if is_uppercase_alpha(c) {
        to_lowercase(c)
    } else {
        c
    }
}

